def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'C' if history[-1][1] == 'C' else 'D'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_d = opp.count('D')
    my_d = me.count('D')
    last_my, last_opp = history[-1]

    # Opponent never defected: exploit near the end while staying safe otherwise.
    if opp_d == 0:
        if n >= 98:
            return 'D'
        return 'C'

    # Opponent always defected: just defect back.
    if opp_d == n:
        return 'D'

    # Recent window analysis
    w = 10 if n >= 10 else n
    rec_opp = opp[-w:]
    rec_me = me[-w:]
    rec_opp_d = rec_opp.count('D')
    rec_me_d = rec_me.count('D')

    # Detect defection streak from opponent
    streak = 0
    for a in reversed(opp):
        if a == 'D':
            streak += 1
        else:
            break

    # Opponent in long defection streak -> punish
    if streak >= 3:
        return 'D'

    # If opponent just defected
    if last_opp == 'D':
        # If opponent almost always cooperates overall, forgive once
        if opp_d <= max(1, n // 20) and n > 12:
            return 'C'
        # If recently very cooperative, forgive to escape DD loops
        if rec_opp_d <= 1 and n > 20:
            return 'C'
        # If we also defected last round, try to restore cooperation sometimes
        if last_my == 'D':
            # After mutual defection, return to C to break deadlock
            if streak == 2 and rng.random() < 0.5:
                return 'C'
            return 'D'
        return 'D'

    # Opponent cooperated last round
    # If opponent has been heavily defective recently, keep punishing
    if rec_opp_d >= 4:
        return 'D'

    # Near end: exploit a clearly cooperative opponent
    remaining = 100 - n
    if remaining <= 2:
        if opp_d <= 3:
            return 'D'
        return 'C'

    # If recent opponent cooperation is high, cooperate
    if rec_opp_d <= 1:
        # Occasional late probe against very cooperative opponents
        if n > 70 and opp_d <= 2 and rng.random() < 0.15:
            return 'D'
        return 'C'

    # Moderate defection: tit-for-tat with mild retaliation
    if rec_opp_d <= 3:
        return 'C'

    # Opponent moderately defective overall; be cautious
    if opp_d * 2 >= n:
        # Mostly defect, occasional cooperate probe if we've been too aggressive
        if rec_me_d >= 4 and rng.random() < 0.3:
            return 'C'
        return 'D'

    return 'C'
